#!/usr/bin/env python3
"""b26_wuerfel_strings.py: Mäxchen: regeln:-Text nach T-078 (Zweifler verliert zwei Leben, 1/3/5 Leben), de/en/es/fr. Trägt einen Text nur ein, wenn es ihn noch nicht in en und fr gibt. Aufruf aus dem Projektordner. Übersetzungen sind Vorschläge."""
import json
KAT = 'App/Ressourcen/Localizable.xcstrings'
U = {
"Du würfelst mit zwei Würfeln verdeckt und siehst nur selbst, was gefallen ist. Dann sagst du einen Wert an – ehrlich oder geblufft –, der höher sein muss als die letzte Ansage. Der Nächste glaubt dir (und würfelt selbst, mit höherer Ansage) oder zweifelt an. Beim Zweifel wird aufgedeckt: War die Ansage nicht gelogen, verliert der Zweifler ein Leben, sonst der Lügner. Stimmte die Ansage „Mäxchen“, verliert der Zweifler sogar zwei Leben. Rangfolge: 31 bis 65 (größere Zahl zuerst), dann Pasche 11 bis 66, am höchsten Mäxchen (2 und 1). Auf Mäxchen muss man aufdecken. Jeder startet mit 1, 3 oder 5 Leben (vor dem ersten Wurf im Menü „Mehr“ wählbar, vorgegeben sind 3), wer übrig bleibt, gewinnt.": ("You roll two dice under a cup and only you see the result. Then you announce a value – honest or bluffed – that must be higher than the last announcement. The next player believes you (and rolls with a higher announcement) or doubts. On a doubt the dice are revealed: if the announcement was not a lie, the doubter loses a life, otherwise the liar does. If the announcement was “Mäxchen” and true, the doubter even loses two lives. Order: 31 to 65 (bigger number first), then pairs 11 to 66, highest is Mäxchen (2 and 1). After Mäxchen you must reveal. Everyone starts with 1, 3 or 5 lives (choose in the “More” menu before the first roll, 3 by default); the last one left wins.", "Lanzas dos dados tapados y solo tú ves el resultado. Luego anuncias un valor, sincero o de farol, que debe ser mayor que el anterior. El siguiente te cree (y tira con un anuncio más alto) o duda. Si duda, se destapan los dados: si el anuncio no era mentira, el que dudó pierde una vida; si no, el mentiroso. Si el anuncio “Mäxchen” era cierto, el que dudó pierde incluso dos vidas. Orden: de 31 a 65 (primero la cifra mayor), luego dobles de 11 a 66 y por último Mäxchen (2 y 1). Tras Mäxchen hay que destapar. Cada uno empieza con 1, 3 o 5 vidas (se elige en el menú «Más» antes de la primera tirada, por defecto 3); gana el último que quede.", "Tu lances deux dés cachés et toi seul vois le résultat. Puis tu annonces une valeur – honnête ou bluffée – qui doit être plus haute que la précédente. Le suivant te croit (et lance avec une annonce plus haute) ou doute. En cas de doute, on dévoile : si l’annonce n’était pas un mensonge, celui qui doute perd une vie, sinon le menteur. Si l’annonce « Mäxchen » était vraie, celui qui doute perd même deux vies. Ordre : de 31 à 65 (le plus grand chiffre d’abord), puis les doubles de 11 à 66, le plus haut est Mäxchen (2 et 1). Après Mäxchen, il faut dévoiler. Chacun commence avec 1, 3 ou 5 vies (au choix dans le menu « Plus » avant le premier lancer, 3 par défaut) ; le dernier en jeu gagne."),
}
cat = json.load(open(KAT)); s = cat['strings']; n = 0
for k, t in U.items():
    loc = s.setdefault(k, {}).setdefault('localizations', {})
    if 'en' in loc and 'fr' in loc: continue
    loc.setdefault('de', {"stringUnit": {"state": "translated", "value": k}})
    for sp, v in zip(('en', 'es', 'fr'), t): loc.setdefault(sp, {"stringUnit": {"state": "translated", "value": v}})
    n += 1
orig = open(KAT).read()
open(KAT, 'w').write(json.dumps(cat, ensure_ascii=False, indent=2, separators=(',', ': ')) + ('\n' if orig.endswith('\n') else ''))
print('eingetragen:', n)
